"""Evaluate temporary selected-row grouping without changing product source."""
from __future__ import annotations

import ast
from pathlib import Path
import runpy
import sys

root = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(root))
from PySide6.QtCore import QModelIndex
from je_file_tree.core.archives import VirtualEntry
from je_file_tree.gui.tree_model import FolderTreeModel, _BATCHED_ROW_MINIMUM

if '--baseline-rows' in sys.argv:
    sys.argv.remove('--baseline-rows')
    path = root / 'build/tree_model_selection_groups_baseline.py'
    tree = ast.parse(path.read_text(encoding='utf-8'))
    source_class = next(node for node in tree.body if isinstance(node, ast.ClassDef) and node.name == 'FolderTreeModel')
    function = next(node for node in source_class.body if isinstance(node, ast.FunctionDef) and node.name == 'selection_rows')
    namespace = dict(globals())
    exec(compile(ast.Module(body=[function], type_ignores=[]), str(path), 'exec'), namespace)
    FolderTreeModel.selection_rows = namespace['selection_rows']

def grouped_rows(self, nodes):
    groups = {}
    for node in nodes:
        if not isinstance(node, VirtualEntry) and self._visible(node):
            groups.setdefault(None if node is self._root else node.parent, []).append(node)
    result = {}
    for parent, entries in groups.items():
        index = self.index_for(parent) if parent is not None else QModelIndex()
        if parent is not None and not index.isValid():
            continue
        if parent is None:
            result[index] = [0] * len(entries)
            continue
        wanted = set(entries)
        if len(wanted) < _BATCHED_ROW_MINIMUM:
            positions = {node: self._row_of(node) for node in wanted}
        else:
            positions = {node: row for row, node in enumerate(self._ordered(parent)) if node in wanted}
        rows = [row for node in entries if (row := positions.get(node, -1)) >= 0]
        if rows:
            result[index] = rows
    return result

if '--group-rows' in sys.argv:
    sys.argv.remove('--group-rows')
    FolderTreeModel.selection_rows = grouped_rows
mapping_records = []
if '--map-stats' in sys.argv:
    sys.argv.remove('--map-stats')
    original = FolderTreeModel.selection_rows
    def mapping(self, nodes):
        before = len(self._rows)
        result = original(self, nodes)
        mapping_records.append({'cache_before': before, 'cache_after': len(self._rows),
                                'mapped_positions': sum(map(len, result.values()))})
        return result
    FolderTreeModel.selection_rows = mapping
if '--verify' in sys.argv:
    sys.argv.remove('--verify')
    import pytest
    raise SystemExit(pytest.main(sys.argv[1:]))
runpy.run_path(str(root / 'build/measure_filter_endpoints.py'), run_name='__main__')
if mapping_records:
    import json
    print(json.dumps({'mapping_records': mapping_records}))
